SELECT version FROM lab_task
WHERE project_id=#{projectId} AND id=#{taskId}
FOR UPDATE

SELECT  FROM lab_task t
LEFT JOIN lab_milestone m ON m.id=t.milestone_id AND m.project_id=t.project_id
LEFT JOIN sys_user u ON u.id=t.assignee_user_id
WHERE t.project_id=#{projectId}
ORDER BY ${sortColumn} ${sortOrder}, t.id ${sortOrder}
LIMIT #{pageSize} OFFSET #{offset}

mapper.update:
UPDATE lab_task SET milestone_id=#{task.milestoneId}, title=#{task.title}, description=#{task.description},
    assignee_user_id=#{task.assigneeUserId}, priority=#{task.priority}, due_date=#{task.dueDate},
    version=version+1, update_time=#{task.updateTime}
WHERE project_id=#{task.projectId} AND id=#{task.id} AND version=#{expectedVersion}

UPDATE lab_task SET status=#{targetStatus}, block_reason=#{blockReason}, version=version+1,
    update_time=#{updateTime}
WHERE project_id=#{projectId} AND id=#{taskId} AND status=#{currentStatus} AND version=#{expectedVersion}
